const byId=id=>products.find(p=>p.id===id);
function notify(t){const el=$('#toast');el.textContent=t;el.setAttribute('role','status');el.setAttribute('aria-live','polite');el.classList.add('show');clearTimeout(notify.timer);const hide=()=>el.classList.remove('show');notify.timer=setTimeout(hide,5000);el.onmouseenter=()=>clearTimeout(notify.timer);el.onmouseleave=()=>{clearTimeout(notify.timer);notify.timer=setTimeout(hide,5000)};el.onfocusin=el.onmouseenter;el.onfocusout=el.onmouseleave}
function displayProductName(p){return window.OrthoLang==='en'?(p.nameEn||window.OrthoJuzoNames?.[p.id]||p.name):p.name}
function updateCounts(){ if(window.OrthoCommerce)cart=window.OrthoCommerce.syncCart(cart,products); $('#cartCount').textContent=cart.reduce((n,x)=>n+x.qty,0);$('#savedCount').textContent=saved.length;persist('ortho-store-cart-v3',cart);persist('ortho-store-saved-v3',saved)}
function imageFile(p){return p.files?.find(f=>f.role==='product')||null}
function productPhoto(f,p,lazy=false){const alt=esc((f.alt?.ar||p.titleAr||p.name)+' / '+(f.alt?.en||p.name));if(f.displayBounds){const[x,y,x2,y2]=f.displayBounds,w=x2-x,h=y2-y;return `<span class="photo-window" style="--crop-ratio:${w}/${h};--crop-width:${w}px;--crop-height:${h}px"><img src="${esc(f.file)}" width="${f.width}" height="${f.height}" ${lazy?'loading="lazy"':''} alt="${alt}" style="width:${f.width/w*100}%;left:${-x/w*100}%;top:${-y/h*100}%"></span>`}return `<img src="${esc(f.file)}" width="${f.width}" height="${f.height}" style="max-width:${f.width}px" ${lazy?'loading="lazy"':''} alt="${alt}">`}
