function productPrice(p){const sale=typeof p.salePrice==='number'&&p.salePrice===p.price&&p.regularPrice>p.price;const discount=sale?Math.round((1-p.price/p.regularPrice)*100):0;const end=sale&&p.saleEnd&&Number.isFinite(Date.parse(p.saleEnd))?`<time class="offer-date" datetime="${esc(p.saleEnd)}">ينتهي العرض: ${esc(new Intl.DateTimeFormat(window.OrthoLang==='en'?'en-GB':'ar-SA',{dateStyle:'medium'}).format(new Date(p.saleEnd)))}</time>`:'';return (p.regularPrice?'<del class="cms-old-price">'+money(p.regularPrice)+'</del> ':'')+`<span class="price-value ${sale?'sale-value':''}">${money(p.price)}</span>`+(sale?`<span class="sale-badge">خصم ${discount}%</span>`:'')+end}
function card(p){return `<article class="product-card"><button class="favorite ${saved.includes(p.id)?'active':''}" data-save="${p.id}" aria-label="${saved.includes(p.id)?'إزالة من':'إضافة إلى'} المفضلة" aria-pressed="${saved.includes(p.id)}">${saved.includes(p.id)?'♥':'♡'}</button>${p.demo?'<span class="badge">السعر يحتاج تأكيدًا</span>':''}<a href="#product/${p.id}" aria-label="عرض ${esc(displayProductName(p))}">${media(p)}</a><div class="product-info"><span class="product-brand">${esc(p.brand)}</span>${juzoBadges(p)}<a href="#product/${p.id}"><h3 dir="auto" ${p.sourceCatalogue?'data-no-translate':''}>${esc(displayProductName(p))}</h3></a><p class="arabic-name">${esc(p.titleAr||groups[p.group]||'تجهيزات التأهيل والعلاج الطبيعي')}</p><div class="card-bottom"><span class="price ${p.price===null?'is-request':''}">${p.price!==null?productPrice(p):'حسب التجهيز'}<small>${p.priceSource==='user-catalogue'?p.priceUnit:p.demo?'السعر يحتاج تأكيدًا':'السعر والتوفر عند الطلب'}</small></span><button class="add-small" data-${p.method==='buy'?'add':'quote'}="${p.id}" ${p.availability==='out-of-stock'?'disabled':''}>${p.availability==='out-of-stock'?'غير متوفر':p.method==='buy'?'أضف للسلة +':'عرض سعر ↗'}</button></div>${p.demoEligible?`<button class="demo-card-link" data-demo-request="${p.id}"><span>احجز عرضًا للجهاز</span><span aria-hidden="true">↗</span></button>`:''}</div></article>`}
function campaign(){const suggestions=window.OrthoCMS.settings.suggestions;return `<div class="recommendations"><div class="recommendation-heading"><div><span class="eyebrow">CURATED FOR YOU</span><h2>اكتشف أيضًا</h2></div><a class="text-link" href="#catalog">كل المنتجات ←</a></div><div class="suggestion-rail" aria-label="اختيارات من عوالم أورثو">${suggestions.map(p=>`<a class="suggestion-card" href="${esc(p.href)}"><div class="suggestion-media ${p.role}"><img src="${esc(p.file)}" width="${p.w}" height="${p.h}" style="max-width:${p.w}px" loading="lazy" alt="${esc(displayProductName(p))} / ${p.role==='lifestyle'?'worn stockings':'studio product view'}"></div><div class="suggestion-copy"><span>${esc(p.tag)}</span><h3 dir="auto">${esc(displayProductName(p))}</h3><p>${esc(p.description)}</p><span class="suggestion-cta">اكتشف المجموعة <i aria-hidden="true">↗</i></span></div></a>`).join('')}</div></div>`}
function identityMark(a){const nativeW=Number(a.width),nativeH=Number(a.height);let image;if(a.displayBounds){const [x,y,x2,y2]=a.displayBounds,w=x2-x,h=y2-y,scale=Math.min(130/w,48/h,1);image=`<span class="identity-crop" style="width:${w*scale}px;height:${h*scale}px"><img src="${esc(a.file)}" width="${nativeW}" height="${nativeH}" style="width:${nativeW*scale}px;height:${nativeH*scale}px;left:${-x*scale}px;top:${-y*scale}px" alt="${esc(a.name)}" loading="lazy"></span>`}else image=`<img src="${esc(a.file)}" width="${nativeW}" height="${nativeH}" style="max-width:${nativeW}px" alt="${esc(a.name)}" loading="lazy">`;return a.href?`<a class="identity-logo" href="${esc(a.href)}" aria-label="${esc(a.name)}">${image}</a>`:`<div class="identity-logo">${image}</div>`}
function trustSection(){return `<section class="wrap trust-section" id="ourPartners"><div class="trust-intro"><div class="trust-year"><span>منذ 2009</span><strong data-no-translate>2009</strong></div><div class="trust-copy"><span class="eyebrow">ORTHOSERV / SAUDI ARABIA</span><h2>خبرة في السوق السعودي.</h2><p>منذ 2009، نخدم الأفراد والمراكز الطبية بحلول التأهيل والتجهيزات الطبية.</p></div><a class="text-link" href="#business">حلول المراكز ↗</a></div><div class="agency-row"><div class="trust-label"><span class="eyebrow">OUR PARTNERS</span><h3>وكلاء وشركاء العلامات</h3><p class="represented-brands">وكلاء Game Ready · Winback · Blueneem · Juzo · LiKAWAVE</p></div><div class="agency-logos">${homeIdentities.brands.map(identityMark).join('')}</div></div><div class="partner-row"><div class="partner-title"><div><span class="eyebrow">OUR CLIENTS</span><h3>عملاؤنا وشركاء نعتز بثقتهم</h3></div><p>مستشفيات ومراكز طبية نعمل معها</p></div><div class="partner-logos">${homeIdentities.clients.map(identityMark).join('')}</div><p class="partner-more">والمزيد من شركاء القطاع الصحي</p></div></section>`}
