function homeJuzoCard(p){const href='#product/juzo-'+encodeURIComponent(p.id);return `<article class="product-card home-juzo-card"><span class="badge">Juzo</span><a href="${href}"><div class="product-media"><img src="experiences/juzo/${esc(p.image)}" width="${Number(p.width)||367}" height="${Number(p.height)||547}" loading="lazy" alt="${esc(p.alt||p.name)}"></div></a><div class="product-info"><span class="product-brand">JUZO</span><a href="${href}"><h3 dir="auto">${esc(displayProductName(p))}</h3></a><p class="arabic-name">${homeSectionText(p.title,p.alt||p.name)}</p><div class="card-bottom"><span class="price is-request">${homeSectionText('تواصل معنا لمعرفة السعر','Price on request')}</span><a class="add-small" href="${href}">${homeSectionText('استعرض المنتج ↗','View product ↗')}</a></div></div></article>`}
function homeActiveCampaign(offer,product){
 if(!offer||offer.paused||!Array.isArray(offer.products)||!offer.products.includes(product.id)||!offer.products.every(id=>byId(id)))return false;
 if(!['percentage','fixed','bundle','accessory'].includes(offer.type))return false;
 if(offer.type==='accessory'&&!byId(offer.accessory))return false;
 const now=Date.now(),start=offer.start?Date.parse(offer.start):-Infinity,end=offer.end?Date.parse(offer.end):Infinity;
 return start<=now&&now<end;
}
function homeTopOfferProducts(){
 const numeric=value=>typeof value==='number'&&Number.isFinite(value)&&value>=0;
 return products.filter(p=>{
  if(p.visible===false||['draft','hidden'].includes(p.commerce?.status))return false;
  const campaign=p.commerce?.appliedOffer;
  if(campaign&&!homeActiveCampaign(campaign,p))return false;
  const discount=numeric(p.price)&&numeric(p.regularPrice)&&p.regularPrice>p.price;
  return discount||homeActiveCampaign(campaign,p);
 }).sort((a,b)=>{const discount=p=>typeof p.regularPrice==='number'&&p.regularPrice>0&&typeof p.price==='number'?1-p.price/p.regularPrice:0;return discount(b)-discount(a)});
}
function homeTopOfferCard(p){
 const campaign=p.commerce?.appliedOffer;
 let html=card(p);
 // Open the real product page; this section does not change its purchasing configuration.
 html=html.replace(/<button class="add-small"[^>]*>[^<]*<\/button>/,`<a class="add-small top-offer-details" href="#product/${esc(p.id)}">${homeSectionText('تفاصيل المنتج ↗','Product details ↗')}</a>`);
 let label='';
 if(campaign?.type==='bundle')label=homeSectionText('ضمن عرض باقة','Part of a bundle offer');
 else if(campaign?.type==='accessory')label=homeSectionText('هدية مع المنتج','Gift with this product');
 else if(typeof p.regularPrice==='number'&&p.regularPrice>p.price)label=homeSectionText('خصم '+Math.round((1-p.price/p.regularPrice)*100)+'%','Save '+Math.round((1-p.price/p.regularPrice)*100)+'%');
 else if(campaign)label=homeSectionText('عرض نشط','Active offer');
 if(label)html=html.replace(/<span class="sale-badge">[^<]*<\/span>/,'');
 if(label)html=html.replace('<div class="product-info">',`<div class="product-info"><span class="top-offer-label">${label}</span>`);
 if(campaign&&homeActiveCampaign(campaign,p)){
  const description=campaign.type==='accessory'?byId(campaign.accessory):null;
  const caption=description?homeSectionText('الهدية: '+(description.titleAr||description.name),'Gift: '+description.name):homeSectionText(campaign.name?.ar||'عرض نشط',campaign.name?.en||'Active offer');
  html=html.replace('<div class="card-bottom">',`<p class="top-offer-caption">${caption}</p><div class="card-bottom">`);
 }
 return html;
}
