function home(){main.innerHTML=`<section class="hero hero-carousel" id="homeCarousel" aria-label="مجموعات أورثو سيرف" aria-roledescription="carousel"><div class="hero-track">
<div class="hero-slide is-active" data-slide="0" role="group" aria-label="1 / 3 — OrthoServ" aria-roledescription="slide"><div class="wrap hero-inner"><div class="hero-copy reveal"><span class="eyebrow">ORTHOSERV / MOVE FORWARD</span><h1>كل خطوة للأمام،<br>تبدأ <span>بعناية.</span></h1><p>أجهزة التأهيل، تجهيزات اللياقة، ومنتجات العناية اليومية. اختياراتك للحركة في مكان واحد.</p><div class="hero-actions"><a class="button" href="#catalog">تسوّق المجموعة <span>←</span></a><a class="text-link" href="#business">تجهيز المراكز ↗</a></div></div><div class="hero-visual"><span class="hero-index">01 / REHABILITATION</span><img src="assets/products/rehab/game-ready-med4-elite.webp" width="1165" height="1043" alt="Game Ready MED4 Elite، الجهاز كاملًا / full device studio view" fetchpriority="high"><a class="hero-label" href="#product/med4">FEATURED EQUIPMENT<strong>Game Ready MED4 Elite ↗</strong></a></div></div></div>
<div class="hero-slide slide-juzo" data-slide="1" role="group" aria-label="2 / 3 — Juzo" aria-roledescription="slide" aria-hidden="true" inert><div class="wrap hero-inner"><div class="hero-copy"><img class="hero-juzo-logo" src="experiences/juzo/assets/juzo-logo.svg" width="100" height="40" alt="Juzo"><span class="eyebrow">JUZO / FREEDOM IN MOTION</span><h1>حركة أخف.<br><span>يوم أقرب لك.</span></h1><p>اكتشف الجوارب والأكمام الطبية، واختَر ما يناسب يومك في عالم Juzo.</p><div class="hero-actions"><a class="button" href="experiences/juzo/">اكتشف عالم Juzo <span>↗</span></a><a class="text-link" href="experiences/juzo/#catalog">استعرض مجموعة Juzo ↗</a></div></div><div class="hero-visual juzo-hero-art"><span class="hero-index">02 / MEDICAL COMPRESSION</span><span class="juzo-hero-orbit" aria-hidden="true"></span><canvas id="heroJuzoCanvas" role="img" aria-label="رجل بجورب ضغط رمادي تتحرك بخطوة خفيفة، تصور إعلاني"></canvas><span class="hero-leg-shadow" aria-hidden="true"></span><span class="hero-art-note">تصور إعلاني للحركة</span></div></div></div>
<div class="hero-slide slide-shockwave" data-slide="2" role="group" aria-label="3 / 3 — EMS Shockwave" aria-roledescription="slide" aria-hidden="true" inert><iframe class="approved-shockwave-scene" title="مشهد EMS DolorClast المعتمد / Approved shockwave scene" src="experiences/shockwave/hero-embed.html" loading="eager"></iframe></div>
</div><div class="hero-carousel-controls wrap"><div class="hero-slide-select" role="group" aria-label="اختيار المشهد"><button class="hero-dot active" data-hero-go="0" aria-label="عرض مشهد أورثو سيرف" aria-pressed="true"><span class="dot-number">01</span><span class="dot-name">OrthoServ</span><i aria-hidden="true"></i></button><button class="hero-dot" data-hero-go="1" aria-label="عرض مشهد Juzo" aria-pressed="false"><span class="dot-number">02</span><span class="dot-name">Juzo</span><i aria-hidden="true"></i></button><button class="hero-dot" data-hero-go="2" aria-label="عرض مشهد الشوك ويف" aria-pressed="false"><span class="dot-number">03</span><span class="dot-name">EMS Shockwave</span><i aria-hidden="true"></i></button></div><div class="hero-playback"><button id="heroPrevious" aria-label="المشهد السابق">‹</button><button id="heroNext" aria-label="المشهد التالي">›</button><span class="hero-control-rule" aria-hidden="true"></span><button id="heroPause" aria-label="إيقاف العرض التلقائي" aria-pressed="false"><span aria-hidden="true">Ⅱ</span><span class="pause-text">إيقاف الحركة</span></button></div><span id="heroAnnouncement" class="sr" role="status" aria-live="polite"></span></div></section>${homeCategories()}${homeReservedSection()}${homeTopOffers()}${homeProductRows()}<section class="wrap section" style="padding-top:0">${campaign()}</section>${experiencePromos()}${trustSection()}${business()}`;window.OrthoCMS.apply();window.initHeroCarousel?.();window.initTrustMarquees?.();initHomeProductRows()}
function currentCategory(){if(location.hash.startsWith('#brand/'))return 'all';return location.hash.split('/')[1]==='blueneem'?'medical':location.hash.split('/')[1]||'all'}
// Optional source-backed Juzo catalogue fields; legacy products keep their existing rendering.
function juzoOrder(p){const linked=(window.OrthoCMS.settings.juzoCatalogue||[]).find(x=>x.id===p.id);return Number.isFinite(p.sortOrder)?p.sortOrder:Number.isFinite(linked?.sortOrder)?linked.sortOrder:Number.MAX_SAFE_INTEGER}
function juzoMatchesGroup(p,key){if(p.group===key)return true;if(p.brand!=='Juzo')return false;return (window.OrthoCMS.settings.juzoTaxonomy||[]).some(node=>node.id===key&&node.productIds.includes(p.id))}
function juzoGroupOptions(){const nodes=window.OrthoCMS.settings.juzoTaxonomy||[];const extra=Object.entries(groups).filter(([id])=>!nodes.some(node=>node.id===id)&&products.some(p=>p.brand==='Juzo'&&p.group===id)).map(([id,label])=>({id,label,parent:null}));return [...nodes,...extra].map(node=>`<option value="${esc(node.id)}" ${filterGroup===node.id?'selected':''}>${node.parent?'— ':''}${esc(node.label)}</option>`).join('')}
function juzoBadges(p){if(p.sourceCatalogue!=='healfit-juzo')return '';const labels=[...(p.pieceTypes||[]),...(p.compressionClasses||[])];return labels.length?`<div class="juzo-import-badges" aria-label="نوع القطعة وفئة الضغط">${labels.map(label=>`<span class="juzo-import-pill" data-no-translate>${esc(label)}</span>`).join('')}</div>`:''}
function juzoOptionsMarkup(p){return `<div class="juzo-import-options">${(p.juzoOptions||[]).map(group=>`<label class="juzo-import-option"><span>${esc(group.labelAr)}</span><select data-juzo-option-label="${esc(group.labelAr)}" aria-label="${esc(group.labelAr)}">${group.values.map(value=>`<option value="${esc(value)}" data-no-translate>${esc(value)}</option>`).join('')}</select></label>`).join('')}</div><p class="small">الخيارات للاستفسار؛ التوافق والتوفر يُؤكدان مع الفريق.</p>`}
function bindJuzoOptions(p){if(p.sourceCatalogue!=='healfit-juzo')return;const fields=[...main.querySelectorAll('[data-juzo-option-label]')];const sync=()=>{chosen=fields.map(field=>field.dataset.juzoOptionLabel+': '+field.value).join(' · ')};fields.forEach(field=>field.addEventListener('change',sync));sync()}
function juzoSizeGuide(p){if(p.sourceCatalogue!=='healfit-juzo')return '';const guide=p.sizeGuide;if(!guide)return '';const tables=guide.tables||[];return `<details class="juzo-import-guide" data-juzo-size-guide open><summary>دليل القياس</summary>${guide.unit==='cm'?'<p>القياسات بالسنتيمتر (cm).</p>':''}${tables.map(table=>`<div class="juzo-import-table" tabindex="0" role="region" aria-label="جدول المقاسات"><table>${table.caption?`<caption data-no-translate>${esc(table.caption)}</caption>`:''}<tbody>${table.rows.map(row=>`<tr>${row.map(cell=>{const tag=cell.heading?'th':'td';return `<${tag} colspan="${Math.max(1,Number(cell.colspan)||1)}" rowspan="${Math.max(1,Number(cell.rowspan)||1)}" data-no-translate>${esc(cell.text)}</${tag}>`}).join('')}</tr>`).join('')}</tbody></table></div>`).join('')}<p class="small">يُراجع المقاس وفئة الضغط مع المختص قبل الطلب.</p></details>`}

// The menu uses observed source columns and existing local group filters; no header/routes are replaced.
// Original OrthoServ UI pictograms; the blue region identifies the garment coverage.
function juzoPieceIcon(kind){
 if(kind==='hand')return `<img class="juzo-piece-figure juzo-glove-icon" src="assets/icons/juzo-glove.svg" width="26" height="44" alt="" aria-hidden="true">`;
 const body='<g class="juzo-figure-base"><circle cx="24" cy="7" r="4.5"/><path d="M22 11h4v5h-4zM19 16Q24 14 29 16l2 15-2 7 1 12 2 21-5 1-3-22-3 22-5-1 2-21 1-12-2-7zM18 17l-3 1-5 19 3 1 7-18zM30 17l3 1 5 19-3 1-7-18zM16 69l5 1-1 5h-8v-3zM27 70l5-1 4 3v3h-8z"/></g>';
 const legs={AD:'M17.3 54h5L21 70l-1 5h-8v-3l4.2-3zM25.7 54h5l1.1 15 4.2 3v3h-8l-1-5z',AG:'M18.6 39h4.8L24 50l-3 20-1 5h-8v-3l4-3 2-19zM24.6 39h4.8L30 50l2 19 4 3v3h-8l-1-5-3-20z',AT:'M18 31h12l-1 7 1 12 2 19 4 3v3h-8l-1-5-3-20-3 20-1 5h-8v-3l4-3 2-19 1-12z',ATU:'M18 26h12l1 5-2 7 1 12 2 19 4 3v3h-8l-1-5-3-20-3 20-1 5h-8v-3l4-3 2-19 1-12-2-7z'};
 let image;
 if(legs[kind])image=body+`<path class="juzo-figure-garment" d="${legs[kind]}"/>`;
 else if(kind==='arm')image='<path class="juzo-figure-base" d="M24 7q8-3 11 5l3 24-6 30-1 10h-8l1-12 4-25-8-20q-3-8 4-12Z"/><path class="juzo-figure-garment" d="m22 18 11-3 5 21-6 30-9-2 5-25Z"/>';
 else if(kind==='pad')image='<rect class="juzo-figure-base" x="8" y="13" width="32" height="54" rx="7"/><path class="juzo-figure-garment" d="M14 20h20v40H14z"/><path class="juzo-figure-line" d="m17 27 14 14m-14 0 14 14"/>';
 else if(kind==='device')image='<path class="juzo-figure-base" d="M8 42h32v27H8z"/><path class="juzo-figure-garment" d="M11 46h26v10H11z"/><path class="juzo-figure-line" d="M24 42V27q0-12 12-12M15 62h3m6 0h3"/>';
 else if(kind==='face')image=body+'<path class="juzo-figure-garment" d="M19 6q5-6 10 0v5l-5 4-5-4Zm3 7h4v5h-4Z"/>';
 else if(kind==='chest')image=body+'<path class="juzo-figure-garment" d="m19 17 5 2 5-2 1 12H18Z"/>';
 else if(kind==='waist')image=body+'<path class="juzo-figure-garment" d="M18 27h12l-1 11H19Z"/>';
 else if(kind==='shorts')image=body+'<path class="juzo-figure-garment" d="M19 32h10l1 18-6-1-6 1Z"/>';
 else if(kind==='body')image=body+'<path class="juzo-figure-garment" d="M19 16q5 3 10 0l2 15-2 7 1 12-6-1-6 1 1-12-2-7Z"/>';
 else if(kind==='foot')image='<path class="juzo-figure-base" d="M23 9h13L32 55q0 8-7 10L8 69q-6-2-2-7l12-11Z"/><path class="juzo-figure-garment" d="m18 50 14 3q0 10-7 12L8 69q-6-2-2-7Z"/>';
 else if(kind==='stump')image='<path class="juzo-figure-base" d="M17 8h14l2 25H15Z"/><path class="juzo-figure-garment" d="M13 28h22l-2 32q-1 11-9 11t-9-11Z"/>';
 else if(kind==='wrap')image=body+`<path class="juzo-figure-garment" d="${legs.AD}"/><path class="juzo-figure-band" d="M17 59h5m-5 5h4m6-5h4m-4 5h4"/>`;
 else if(kind==='measure')image=body+'<path class="juzo-figure-line" d="M42 17v55m-4-55h7m-5 11h5m-7 11h7m-5 11h5m-7 11h7m-5 11h5"/>';
 else image=body+`<path class="juzo-figure-garment" d="${legs.AT}"/>`;
 return `<svg class="juzo-piece-figure" viewBox="0 0 48 80" width="26" height="44" aria-hidden="true" focusable="false">${image}</svg>`;
}
function juzoCategoryIcon(group){if(group.startsWith('custom-made__'))return 'measure';if(/arm-sleeves/.test(group))return 'arm';if(/gloves$/.test(group))return 'hand';if(/face-masks/.test(group))return 'face';if(/bras|thorax/.test(group))return 'chest';if(/tummy-tuck|abdominal-binders/.test(group))return 'waist';if(/bbl|post-partum/.test(group))return 'shorts';if(/liposuction/.test(group))return 'body';if(/lipo-foam|foam-padding/.test(group))return 'pad';if(/toe-caps/.test(group))return 'foot';if(/stump-shrinkers/.test(group))return 'stump';if(/wrap/.test(group))return 'wrap';if(/pumps/.test(group))return 'device';return 'AT'}

let juzoNavPiece='',juzoNavPressure='';
function juzoNavigationMarkup(cat){if(filterBrand!=='Juzo'&&cat!=='compression')return '';const menus=window.OrthoCMS.settings.juzoNavigation||[];return `<nav class="wrap juzo-category-nav" aria-label="أقسام جوزو">${menus.map(menu=>`<details class="juzo-category-menu"><summary>${esc(menu.label)}</summary><div class="juzo-category-panel" id="juzo-menu-${esc(menu.groupId)}" style="--juzo-menu-columns:${menu.columns.length}">${menu.columns.map(column=>`<div class="juzo-category-column">${column.map((item,i)=>`${item.heading!==column[i-1]?.heading?`<p class="juzo-category-heading">${esc(item.heading)}</p>`:''}<div class="juzo-category-entry"><button type="button" class="juzo-category-link ${filterGroup===item.groupId?'is-current':''}" data-juzo-nav-group="${esc(item.groupId)}" ${filterGroup===item.groupId?'aria-current="true"':''}>${esc(item.label)}</button>${item.groupId?`<div class="juzo-category-codes" aria-label="نوع القطعة وفئة الضغط">${item.pieceTypes.map(code=>`<button type="button" class="juzo-piece-code" data-juzo-nav-group="${esc(item.groupId)}" data-juzo-nav-piece="${esc(code)}" aria-pressed="${filterGroup===item.groupId&&juzoNavPiece===code}" title="${esc(item.label)} — ${esc(code)}" aria-label="${esc(item.label)} — ${esc(code)}" data-no-translate>${juzoPieceIcon(code)}<span>${esc(code)}</span></button>`).join('')}${!item.pieceTypes.length?`<button type="button" class="juzo-piece-code juzo-category-figure" data-juzo-nav-group="${esc(item.groupId)}" title="${esc(item.label)}" aria-label="${esc(item.label)}">${juzoPieceIcon(juzoCategoryIcon(item.groupId))}</button>`:''}${item.pressureClasses.map(code=>`<button type="button" class="juzo-pressure-code" data-juzo-nav-group="${esc(item.groupId)}" data-juzo-nav-pressure="${esc(code)}" aria-pressed="${filterGroup===item.groupId&&juzoNavPressure===code}" data-no-translate>${esc(code)}</button>`).join('')}</div>`:''}</div>`).join('')}</div>`).join('')}<aside class="juzo-category-preview"><span class="eyebrow" data-no-translate>ORTHOSERV / JUZO</span><img src="assets/products/juzo/orthoserv-catalogue-placeholder.svg" width="640" height="640" alt="صورة توضيحية بهوية أورثو سيرف"><h2>${esc(menu.label)}</h2><p>تصفّح القطع حسب احتياجك، وأكّد المقاس والتوفر مع فريقنا.</p><button type="button" class="button" data-juzo-nav-group="${esc(menu.groupId)}">استعرض القسم <span aria-hidden="true">←</span></button></aside></div></details>`).join('')}</nav>`}
function juzoActiveNavFilters(){return juzoNavPiece||juzoNavPressure?`<div class="juzo-active-nav-filters"><span data-no-translate>${esc([juzoNavPiece,juzoNavPressure].filter(Boolean).join(' · '))}</span><button type="button" class="text-link small" data-juzo-clear-nav>مسح الفلاتر</button></div>`:''}
function bindJuzoNavigation(){const clear=main.querySelector('[data-juzo-clear-nav]');if(clear)clear.onclick=()=>{juzoNavPiece='';juzoNavPressure='';catalog(currentCategory())};const nav=main.querySelector('.juzo-category-nav');if(!nav)return;const menus=[...nav.querySelectorAll('.juzo-category-menu')];const closeOthers=selected=>menus.forEach(menu=>{if(menu!==selected){menu.open=false;menu._openedByHover=false}});menus.forEach(menu=>{const summary=menu.querySelector('summary');menu.addEventListener('toggle',()=>{if(menu.open)closeOthers(menu);else menu._openedByHover=false});if(window.matchMedia?.('(hover: hover) and (pointer: fine)').matches){summary.addEventListener('mouseenter',()=>{if(!menu.open){menu._openedByHover=true;closeOthers(menu);menu.open=true}});summary.addEventListener('click',event=>{if(event.detail&&menu._openedByHover){event.preventDefault();menu._openedByHover=false;menu.open=true}})}});nav.addEventListener('mouseleave',()=>{if(!nav.contains(document.activeElement))closeOthers(null)});nav.addEventListener('click',event=>{const button=event.target.closest('[data-juzo-nav-group]');if(!button)return;const id=button.dataset.juzoNavGroup;if(!(window.OrthoCMS.settings.juzoTaxonomy||[]).some(node=>node.id===id))return;const piece=button.dataset.juzoNavPiece,pressure=button.dataset.juzoNavPressure;if(filterGroup!==id||(!piece&&!pressure)){juzoNavPiece='';juzoNavPressure=''}if(piece)juzoNavPiece=juzoNavPiece===piece?'':piece;if(pressure)juzoNavPressure=juzoNavPressure===pressure?'':pressure;filterGroup=id;page=1;catalog(currentCategory());main.querySelector('#groupFilter')?.focus()});nav.addEventListener('keydown',event=>{if(event.key==='Escape'){const menu=event.target.closest('.juzo-category-menu');if(menu?.open){event.preventDefault();menu.open=false;menu._openedByHover=false;menu.querySelector('summary').focus()}return}if(event.target.tagName!=='SUMMARY')return;const summaries=menus.map(menu=>menu.querySelector('summary')),index=summaries.indexOf(event.target);let next;if(event.key==='Home')next=0;else if(event.key==='End')next=summaries.length-1;else if(['ArrowLeft','ArrowRight'].includes(event.key)){const rtl=document.documentElement.dir==='rtl';const step=(event.key==='ArrowRight'?1:-1)*(rtl?-1:1);next=(index+step+summaries.length)%summaries.length}if(next!==undefined){event.preventDefault();closeOthers(null);summaries[next].focus()}})}
document.addEventListener('pointerdown',event=>{const nav=main.querySelector('.juzo-category-nav');if(nav&&!nav.contains(event.target))nav.querySelectorAll('details[open]').forEach(menu=>{menu.open=false})});

function catalog(cat){if(!filterGroup){juzoNavPiece='';juzoNavPressure=''}const label=brandView||categories[cat]||categories.all;let list=products.filter(p=>cat==='all'||(cat==='saved'?saved.includes(p.id):p.category===cat||cat==='rehab'&&p.id==='spirit'));const brands=[...new Set(list.map(p=>p.brand))].sort();list=list.filter(p=>(!query||(p.name+' '+p.titleAr+' '+p.brand+' '+p.model).toLowerCase().includes(query.toLowerCase()))&&(!filterBrand||p.brand===filterBrand)&&(!filterMethod||p.method===filterMethod)&&(!filterGroup||juzoMatchesGroup(p,filterGroup))&&(!juzoNavPiece||(p.pieceTypes||[]).includes(juzoNavPiece))&&(!juzoNavPressure||(p.compressionClasses||[]).includes(juzoNavPressure)));if(sorting==='featured'&&(filterBrand==='Juzo'||cat==='compression'&&list.every(p=>p.brand==='Juzo')))list.sort((a,b)=>juzoOrder(a)-juzoOrder(b));if(sorting==='price-asc')list.sort((a,b)=>(a.price??Infinity)-(b.price??Infinity));if(sorting==='price-desc')list.sort((a,b)=>(b.price??-1)-(a.price??-1));if(sorting==='name')list.sort((a,b)=>a.name.localeCompare(b.name));const pageSize=12,pages=Math.ceil(list.length/pageSize);page=Math.max(1,Math.min(page,pages||1));main.innerHTML=`${juzoNavigationMarkup(cat)}<section class="catalog-intro ${cat==='gym'?'gym':''}"><div class="wrap"><div class="breadcrumb"><a href="#home">الرئيسية</a> / ${esc(label)}</div><span class="eyebrow">ORTHOSERV COLLECTION</span><h1>${query?'نتائج البحث':esc(label)}</h1><p>${query?'نتائج البحث عن «'+esc(query)+'»':cat==='gym'?'تجهيزات للحركة والتمرين.':'اختيارات محددة، وتفاصيل تساعدك على اتخاذ الخطوة التالية.'}</p></div></section><div class="wrap catalog-layout"><aside class="filters" id="filters"><h3>تصفية المنتجات</h3><div class="filter-group"><strong>الأقسام</strong>${Object.entries(categories).filter(([k])=>k!=='saved').map(([k,v])=>`<a class="filter-link ${k===cat?'active':''}" href="${'#catalog'+(k==='all'?'':'/'+k)}">${v} <span>←</span></a>`).join('')}</div><div class="filter-group"><strong>العلامة التجارية</strong><select id="brandFilter" aria-label="العلامة التجارية"><option value="">كل العلامات</option>${brands.map(b=>`<option ${filterBrand===b?'selected':''} value="${esc(b)}">${esc(b)}</option>`).join('')}</select></div><div class="filter-group"><strong>نوع المنتج</strong><select id="groupFilter" aria-label="نوع المنتج"><option value="">كل الأنواع</option>${(filterBrand==='Juzo'||cat==='compression')?juzoGroupOptions():Object.entries(groups).filter(([k])=>products.some(p=>(cat==='all'||p.category===cat||cat==='rehab'&&p.id==='spirit')&&p.group===k&&(!brandView||p.brand===filterBrand))).map(([k,v])=>`<option value="${k}" ${filterGroup===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="filter-group"><strong>طريقة الطلب</strong><button class="filter-link ${!filterMethod?'active':''}" data-method="">كل المنتجات</button><button class="filter-link ${filterMethod==='buy'?'active':''}" data-method="buy">شراء مباشر</button><button class="filter-link ${filterMethod==='quote'?'active':''}" data-method="quote">طلب عرض سعر</button></div><button class="text-link small" id="clearFilters">مسح الفلاتر</button></aside><section class="catalog-main" aria-label="المنتجات"><div class="catalog-toolbar"><form class="catalog-search" id="catalogSearchForm" role="search"><input type="search" id="catalogSearch" aria-label="ابحث في المتجر" placeholder="ابحث في المتجر" value="${esc(query)}"><button aria-label="بحث">⌕</button></form><button class="filter-toggle" id="filterToggle" aria-expanded="false">الفلاتر +</button><p>${list.length} منتج${query?' مطابق':''}</p><select id="sort" aria-label="ترتيب المنتجات"><option value="featured">المختارات أولًا</option><option value="price-asc">السعر: الأقل أولًا</option><option value="price-desc">السعر: الأعلى أولًا</option><option value="name">الاسم</option></select></div>${juzoActiveNavFilters()}${list.length?`<div class="product-grid">${list.slice((page-1)*pageSize,page*pageSize).map(card).join('')}</div>`:`<div class="empty"><h3>${cat==='saved'?'مفضلتك في انتظار اختياراتك':'لا توجد منتجات مطابقة'}</h3><p>جرّب قسمًا آخر أو امسح الفلاتر.</p><button class="button secondary" id="clearEmpty">عرض كل المنتجات</button></div>`}${pages>1?`<div class="pagination" aria-label="صفحات المنتجات">${Array.from({length:pages},(_,i)=>`<button data-page="${i+1}" class="${page===i+1?'active':''}" aria-label="صفحة ${i+1}">${i+1}</button>`).join('')}</div>`:''}</section></div>`;$('#catalogSearchForm').onsubmit=e=>{e.preventDefault();query=$('#catalogSearch').value.trim();$('#search').value=query;page=1;catalog(cat)};$('#sort').value=sorting;$('#sort').onchange=e=>{sorting=e.target.value;catalog(cat)};$('#brandFilter').onchange=e=>{filterBrand=e.target.value;page=1;catalog(cat)};$('#groupFilter').onchange=e=>{filterGroup=e.target.value;juzoNavPiece='';juzoNavPressure='';page=1;catalog(cat)};$('#clearFilters').onclick=resetFilters;$('#clearEmpty')?.addEventListener('click',()=>{resetFilters();location.hash='catalog'});$('#filterToggle').onclick=()=>{const open=$('#filters').classList.toggle('open');$('#filterToggle').setAttribute('aria-expanded',open)};bindJuzoNavigation();}
function resetFilters(){brandView='';filterBrand='';filterMethod='';filterGroup='';query='';$('#search').value='';page=1;catalog(currentCategory())}
function productTabs(){const extra=$('.detail-extra');if(!extra)return;const original=[...extra.children];const files=document.createElement('details');files.innerHTML='<summary>ملفات المنتج</summary>';files.id='productFiles';original.filter(node=>node.tagName==='P'&&node.querySelector('a')).forEach(node=>files.append(node));if(!files.querySelector('a'))files.insertAdjacentHTML('beforeend','<p>لا توجد ملفات مرفقة لهذا المنتج.</p>');extra.append(files);const panels=[...extra.querySelectorAll(':scope > details')];const nav=document.createElement('div');nav.className='product-tabs';nav.setAttribute('role','tablist');nav.setAttribute('aria-label','تفاصيل المنتج');panels.forEach((panel,i)=>{panel.id=panel.id||'productPanel'+i;panel.open=true;panel.hidden=i!==0;panel.setAttribute('role','tabpanel');const button=document.createElement('button');button.type='button';button.id='productTab'+i;button.textContent=panel.querySelector('summary').textContent;button.setAttribute('role','tab');button.setAttribute('aria-controls',panel.id);button.setAttribute('aria-selected',String(i===0));button.tabIndex=i===0?0:-1;panel.setAttribute('aria-labelledby',button.id);button.onclick=()=>{panels.forEach((p,j)=>{p.hidden=i!==j;const b=nav.children[j];b.setAttribute('aria-selected',String(i===j));b.tabIndex=i===j?0:-1})};button.onkeydown=e=>{if(e.key==='Home'||e.key==='End'){e.preventDefault();const target=nav.children[e.key==='Home'?0:panels.length-1];target.click();target.focus();return}let step=e.key==='ArrowRight'?1:e.key==='ArrowLeft'?-1:0;if(document.documentElement.dir==='rtl')step=-step;if(step){e.preventDefault();const next=nav.children[(i+step+panels.length)%panels.length];next.click();next.focus()}};nav.append(button)});extra.prepend(nav)}
function product(id){const p=byId(id);if(!p){main.innerHTML='<div class="wrap empty"><h1>المنتج غير موجود</h1><a class="text-link" href="#catalog">العودة للمنتجات</a></div>';return}activeProduct=p;quantity=1;chosen=p.options?.[0]||'';const f=imageFile(p);const files=[...p.files.filter(f=>f.role==='product'),...p.files.filter(f=>f.role!=='product')];main.innerHTML=`<section class="wrap detail"><div class="breadcrumb"><a href="#home">الرئيسية</a> / <a href="#catalog/${p.category}">${categories[p.category]}</a> / ${esc(displayProductName(p))}</div><div class="detail-grid"><div><div id="detailStage" class="detail-stage">${f?productPhoto(f,p):'<div class="placeholder"><strong>'+esc(displayProductName(p))+'</strong><span>صورة المنتج</span></div>'}</div>${files.length?`<div class="detail-thumbs">${files.map((x,i)=>`<button data-photo="${i}" aria-label="صورة ${i+1}${x.role==='lifestyle'?' أثناء الاستخدام':''}"><img src="${esc(x.file)}" width="${x.width}" height="${x.height}" loading="lazy" alt="${esc(x.alt?.ar||p.name)}"></button>`).join('')}</div>`:''}</div><div class="detail-copy"><span class="eyebrow">${esc(p.brand)}</span><h1 dir="auto" ${p.sourceCatalogue?'data-no-translate':''}>${esc(displayProductName(p))}</h1><p class="subtitle">${esc(p.titleAr||groups[p.group]||'أجهزة التأهيل والعلاج الطبيعي')}</p><div class="detail-price"><strong>${p.price!==null?productPrice(p):'اطلب عرض سعر'}</strong><p>${p.priceSource==='user-catalogue'?'سعر العلبة حسب الكتالوج المرفق. التوفر والضريبة يُؤكدان عند الطلب.':p.demo?'السعر يحتاج تأكيدًا من الفريق قبل الطلب.':'يُحدد حسب التجهيز والكمية والخدمات. التوفر يُؤكد مع الفريق.'}</p></div>${p.imageNote?`<p class="pack-note">${esc(p.imageNote)}</p>`:''}${woundVariants(p)}${p.sourceCatalogue==='healfit-juzo'?juzoOptionsMarkup(p):p.options?.length?`<span class="option-label">اختر المواصفة · خيارات</span><div class="options">${p.options.map((x,i)=>`<button class="option ${i===0?'selected':''}" data-option="${esc(x)}" aria-pressed="${i===0}">${esc(x)}</button>`).join('')}</div>`:''}<div class="detail-actions">${p.method==='buy'?`<div class="qty"><button data-detail-qty="-1" aria-label="تقليل الكمية">−</button><span id="detailQty">1</span><button data-detail-qty="1" aria-label="زيادة الكمية">+</button></div><button class="button" data-add="${p.id}" data-detail="true">أضف إلى السلة +</button>`:`<button class="button" data-quote="${p.id}">اطلب عرض سعر ↗</button>`}<button class="option" data-save="${p.id}" aria-label="المفضلة">${saved.includes(p.id)?'♥':'♡'}</button></div>${p.demoEligible?`<button class="demo-detail-button" data-demo-request="${p.id}"><span>احجز عرضًا للجهاز</span><span aria-hidden="true">↗</span></button>`:''}<div class="detail-notes"><span>${p.group==='wound-care'?'عبوات مستهلكات طبية؛ يُراجع المقاس وعدد الأظرف قبل الطلب.':'التركيب والتدريب: خدمات يمكن طلبها وتُؤكد حسب المنتج.'}</span><span>${p.method==='buy'?'تُحفظ السلة على جهازك حتى مراجعة اختياراتك.':'أكد السعر وموعد التوصيل مع الفريق قبل الطلب.'}</span></div></div></div><div class="detail-extra">${juzoSizeGuide(p)}<details open><summary>عن المنتج</summary><p>${esc(p.demo||p.brand==='HIGHCARE'||p.sourceCatalogue==='healfit-juzo'?p.description:p.titleAr||'جهاز ضمن مجموعة أورثو سيرف. للاطلاع على المواصفات، افتح بيانات الكتالوج أدناه.')}</p></details><details><summary>المواصفات وبيانات الكتالوج</summary><p>${esc(p.description)}</p>${p.model?`<p>الموديل / SKU: ${esc(p.model)}</p>`:''}<p class="small">${p.source?.cell?'من شيت العميل، الخلية '+esc(p.source.cell)+'. تُراجع التفاصيل قبل النشر التجاري.':'المواصفات والتجهيز النهائي يُؤكدان مع الفريق.'}</p></details>${p.source?.document?`<p class="small" style="padding:18px 0"><a class="text-link" href="${esc(p.source.document)}" target="_blank" rel="noopener">كتالوج المنتج المرفق PDF ↗</a></p>`:''}${p.source?.page?`<p class="small" style="padding:18px 0"><a class="text-link" href="${esc(p.source.page)}" target="_blank" rel="noopener noreferrer">تفاصيل المنتج على موقع المصنع ↗</a></p>`:''}<details><summary>الشحن والخدمات</summary><p>في هذا الموقع لا تُحسب مواعيد أو رسوم شحن فعلية. يمكن تحديد المدينة وطلب التركيب أو التدريب ضمن طلب عرض السعر .</p></details></div></section><section class="wrap section"><div class="section-head"><h2>قد يناسبك أيضًا</h2><a class="text-link" href="#catalog/${p.category}">عرض القسم ←</a></div><div class="product-grid">${products.filter(x=>x.category===p.category&&x.id!==p.id).slice(0,4).map(card).join('')}</div></section>`;productTabs();bindJuzoOptions(p);document.querySelectorAll('[data-photo]').forEach(btn=>btn.onclick=()=>{const x=files[Number(btn.dataset.photo)];$('#detailStage').classList.toggle('lifestyle',x.role==='lifestyle');$('#detailStage').innerHTML=productPhoto(x,p)})}
function add(id,detail){const p=byId(id);if(!p||p.method!=='buy'||p.availability==='out-of-stock')return;const option=detail?chosen:p.options?.[0]||'',qty=detail?quantity:1;const item=cart.find(x=>x.id===id&&x.option===option);if(item)item.qty=Math.min(99,item.qty+qty);else cart.push({id,option,qty});updateCounts();notify('تمت الإضافة إلى السلة')}
const totals=()=>{const priced=cart.filter(x=>!window.OrthoJuzoStore?.isEnquiry(x));return priced.reduce((n,x)=>n+(window.OrthoCommerce?window.OrthoCommerce.lineTotal(byId(x.id),x,priced):(byId(x.id)?.price||0)*x.qty),0)};
function showCart(){renderCart();$('#cartDialog').showModal()}
function renderCart(){if(window.OrthoJuzoStore?.renderCart(cart,products,{media,money,lineTotal:(p,x,items)=>window.OrthoCommerce?window.OrthoCommerce.lineTotal(p,x,items):(p.price||0)*x.qty,checkout,openForm}))return;const body=$('#cartBody');body.innerHTML=cart.length?`${cart.map((x,i)=>{const p=byId(x.id);return `<div class="cart-item">${media(p)}<div><a href="#product/${p.id}" data-close-cart><h3>${esc(displayProductName(p))}</h3></a><p>${esc([x.option,p.priceSource==='user-catalogue'?p.priceUnit:'السعر يحتاج تأكيدًا'].filter(Boolean).join(' · '))}</p><div class="cart-item-bottom"><div class="qty"><button data-cart-qty="${i}" data-step="-1" aria-label="تقليل الكمية">−</button><span>${x.qty}</span><button data-cart-qty="${i}" data-step="1" aria-label="زيادة الكمية">+</button></div><strong>${money(window.OrthoCommerce?window.OrthoCommerce.lineTotal(p,x,cart):p.price*x.qty)}</strong><button class="remove" data-remove="${i}">حذف</button></div></div></div>`}).join('')}<div class="cart-total"><div><span>المنتجات</span><span>${money(totals())}</span></div><div><span>الشحن</span><span>يُحدد مع الفريق</span></div><div class="total"><strong>الإجمالي</strong><strong>${money(totals())}</strong></div></div><button class="button wide" id="checkoutBtn">مراجعة السلة ←</button><p class="small" style="margin-top:15px"></p>`:`<div class="empty"><h3>سلتك لسه فاضية</h3><p>استعرض المستلزمات وأضف ما تحتاجه إلى السلة.</p><a class="button" style="margin-top:20px" href="#catalog/consumables" data-close-cart>تصفّح المستهلكات ←</a></div>`;$('#checkoutBtn')?.addEventListener('click',checkout)}
function openForm(title,html){$('#formTitle').textContent=title;$('#formBody').innerHTML=html;$('#formDialog').showModal()}
function requestDemo(p){if(!p?.demoEligible)return;openForm('طلب عرض للجهاز',`<p class="small">راجع تفاصيل عرض الجهاز.</p><div class="demo-form-product"><span class="eyebrow">PRODUCT PRESENTATION</span><strong dir="auto">${esc(displayProductName(p))}</strong></div><form id="demoRequestForm"><div class="form-grid"><label class="field">الاسم<input required autocomplete="name"></label><label class="field">رقم الجوال<input type="tel" required autocomplete="tel" dir="ltr"></label><label class="field">المدينة<input required autocomplete="address-level2"></label><label class="field">اسم المنشأة (اختياري)<input autocomplete="organization"></label><label class="field">طريقة العرض المفضلة<select><option>عرض عن بُعد</option><option>عرض حضوري — حسب التوفر</option></select></label><label class="field">موعد مفضل (اختياري)<input type="date"></label></div><button class="button wide">مراجعة طلب العرض</button></form>`);$('#demoRequestForm').onsubmit=e=>{e.preventDefault();$('#formBody').innerHTML='<div class="success"><b>✓</b><h3>طلب عرض الجهاز جاهز للمراجعة</h3><p>تواصل مع الفريق لتنسيق عرض الجهاز.</p><button class="button" data-close>متابعة التصفح</button></div>'}}
function quote(p){const title=p?'طلب عرض سعر':'تجهيز مركز';openForm(title,`<p class="small">راجع تفاصيل طلبك وتواصل مع فريق أورثو سيرف.</p><form id="quoteForm">${p?`<div class="quote-preview">${media(p)}<h3 dir="auto">${esc(displayProductName(p))}</h3></div>`:''}<div class="form-grid"><label class="field">الاسم<input name="name" required autocomplete="name"></label><label class="field">رقم الجوال<input name="phone" type="tel" required dir="ltr" autocomplete="tel"></label><label class="field">المدينة<input name="city" required autocomplete="address-level2"></label><label class="field">${p?'الكمية':'نوع المنشأة'}${p?'<input type="number" min="1" max="999" value="1" required>':'<select><option>مركز علاج طبيعي</option><option>مستشفى</option><option>نادي أو مركز رياضي</option><option>أخرى</option></select>'}</label></div><label class="field">اسم المنشأة (اختياري)<input name="company" autocomplete="organization"></label><label class="field">الخدمات المطلوبة<select><option>توريد المنتج</option><option>توريد وتركيب</option><option>توريد وتركيب وتدريب</option></select></label><label class="field">${p?'ملاحظات':'الأجهزة والكميات المطلوبة'}<textarea ${p?'':'required'}></textarea></label><button class="button wide">مراجعة تفاصيل الطلب</button></form>`);$('#quoteForm').onsubmit=e=>{e.preventDefault();$('#formBody').innerHTML='<div class="success"><b>تمت المراجعة ✓</b><h3>تفاصيل طلب عرض السعر جاهزة للمراجعة.</h3><p>تواصل مع الفريق لاستكمال طلب عرض السعر.</p><button class="button" data-close>متابعة التصفح</button></div>'}}
function checkout(){const purchased=cart.filter(x=>!window.OrthoJuzoStore?.isEnquiry(x)&&!x.giftFor);if(!purchased.length)return;$('#cartDialog').close();openForm('مراجعة السلة','<div id="orderBox"></div>');window.OrthoOrders?.checkout($('#orderBox'),purchased.map(x=>({id:x.id,option:x.option||'',qty:x.qty})),{money,total:totals(),onPlaced:()=>{cart=cart.filter(x=>window.OrthoJuzoStore?.isEnquiry(x));updateCounts()}})}
function contactSummary(){const c=window.OrthoCMS.settings.contact||{};return `<div class="contact-summary">${['legalName','address','building'].filter(k=>c[k]).map(k=>`<p dir="auto">${esc(c[k])}</p>`).join('')}${['phone','email','whatsapp'].filter(k=>c[k]).map(k=>`<p dir="ltr">${esc(c[k])}</p>`).join('')}</div>`}
function contact(){openForm('تواصل مع أورثو سيرف',`${contactSummary()}<p class="small">اكتب تفاصيل استفسارك.</p><form id="contactForm"><div class="form-grid"><label class="field">الاسم<input required autocomplete="name"></label><label class="field">البريد الإلكتروني<input required type="email" autocomplete="email" dir="ltr"></label></div><label class="field">موضوع الرسالة<select><option>استفسار عن منتج</option><option>مساعدة في الاختيار</option><option>تجهيز مركز</option><option>أخرى</option></select></label><label class="field">رسالتك<textarea required></textarea></label><button class="button wide">مراجعة الرسالة</button></form>`);$('#contactForm').onsubmit=e=>{e.preventDefault();$('#formBody').innerHTML='<div class="success"><b>✓</b><h3>تفاصيل الرسالة جاهزة</h3><p>تواصل مع الفريق لاستكمال استفسارك.</p><button class="button" data-close>متابعة التصفح</button></div>'}}
function ctInfo(){const c=window.OrthoCMS.settings.contact||{};const wa=String(c.whatsapp||'').replace(/\D/g,'');return{c,wa,phone:String(c.phone||'').trim(),email:String(c.email||'').trim(),hours:Array.isArray(c.hours)?c.hours.filter(h=>h&&h.days&&h.time):[],mapUrl:'https://www.google.com/maps/search/?api=1&query='+encodeURIComponent([c.address,c.building].filter(Boolean).join(' '))}}
function fittingBanner(){const{wa}=ctInfo();const en=window.OrthoLang==='en';return `<section class="fit-banner-wrap" data-fit-banner data-no-translate><div class="wrap"><div class="fit-banner"><div class="fit-copy"><span class="eyebrow">FITTING SESSION</span><h2>${en?'Not sure which garment or size is right for you?':'غير متأكد من المنتج أو المقاس المناسب لك؟'}</h2><p>${en?'Talk to a specialist for help choosing the right garment and fit before ordering.':'تحدّث مع مختص يساعدك على اختيار المنتج والمقاس المناسبين قبل الطلب.'}</p></div><div class="fit-actions"><a class="button" href="#contact/fitting">${en?'Book a fitting session':'احجز جلسة القياس'} <span>←</span></a>${wa?`<a class="button ghost" href="https://wa.me/${wa}" target="_blank" rel="noopener noreferrer">${en?'Contact us on WhatsApp':'تواصل عبر واتساب'}</a>`:''}</div></div></div></section>`}
function addFittingBanner(){const[view,arg]=(location.hash||'#home').slice(1).split('/');if(view==='contact')return;document.querySelectorAll('[data-fit-banner]').forEach(el=>el.remove());const p=view==='product'?byId(arg):null;if(view==='home'||view===''||view==='catalog'&&arg==='compression'||view==='brand'&&arg==='juzo'||p&&p.category==='compression')main.insertAdjacentHTML('beforeend',fittingBanner())}
function contactPage(arg){const{c,wa,phone,email,hours,mapUrl}=ctInfo();const topics=['حجز جلسة قياس','مساعدة في اختيار المقاس','استفسار عن منتج','مشكلة في الطلب','تجهيز مركز أو جهة طبية','الاستبدال والإرجاع','استفسار عام'];const addr=[c.address,c.building].filter(Boolean);const chan=[];if(phone)chan.push(['الهاتف',`<a dir="ltr" href="tel:${esc(phone.replace(/[^\d+]/g,''))}">${esc(phone)}</a>`,'اتصال مباشر','M5 4h4l2 5-2.5 1.5a11 11 0 0 0 5 5L15 13l5 2v4a2 2 0 0 1-2 2A16 16 0 0 1 3 6a2 2 0 0 1 2-2Z']);if(email)chan.push(['البريد الإلكتروني',`<a dir="ltr" href="mailto:${esc(email)}">${esc(email)}</a>`,'مراسلة مكتوبة','M3 6h18v12H3zM3 7l9 7 9-7']);if(addr.length)chan.push(['زيارتنا',`<span dir="auto">${addr.map(esc).join('<br>')}</span>`,`<a href="${esc(mapUrl)}" target="_blank" rel="noopener noreferrer">احصل على الاتجاهات ↗</a>`,'M12 21s7-6.2 7-11a7 7 0 0 0-14 0c0 4.8 7 11 7 11ZM12 12.5a2.5 2.5 0 1 0 0-5 2.5 2.5 0 0 0 0 5Z']);document.title='تواصل معنا | OrthoServ';main.innerHTML=`<section class="catalog-intro ct-intro"><div class="wrap"><div class="breadcrumb"><a href="#home">الرئيسية</a> / تواصل معنا</div><span class="eyebrow">CONTACT</span><h1>نحن هنا <b>لمساعدتك.</b></h1><p>سواء كان لديك سؤال عن المقاس، أو تحتاج مساعدة في اختيار المنتج المناسب، أو ترغب في مناقشة طلب لمركزك. فريقنا بجانبك.</p></div></section><div class="wrap ct-body">${wa?`<a class="ct-chat" href="https://wa.me/${wa}" target="_blank" rel="noopener noreferrer"><span class="ct-chat-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M4 20l1.3-4.2A8 8 0 1 1 8.4 18.8L4 20Z"/></svg></span><span class="ct-chat-copy"><small>الأسرع ردًا</small><strong>تحدّث معنا عبر واتساب</strong></span><span class="ct-chat-num" dir="ltr">${esc(c.whatsapp)}</span><span class="menu-arrow">←</span></a>`:''}${chan.length?`<div class="ct-channels">${chan.map(([t,v,n,d])=>`<article class="ct-card"><span class="ct-ico" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="${d}"/></svg></span><small>${t}</small><div class="ct-val">${v}</div><p>${n}</p></article>`).join('')}</div>`:''}<div class="ct-grid"><section class="ct-form-card" id="ctForm"><span class="eyebrow">SEND A MESSAGE</span><h2>كيف يمكننا <b>مساعدتك؟</b></h2><form id="ctFormEl"><div class="form-grid"><label class="field">الاسم الكامل<input name="n" required maxlength="80" autocomplete="name"></label><label class="field">الهاتف / واتساب<input name="p" required type="tel" autocomplete="tel" dir="ltr" placeholder="+966"></label></div><div class="form-grid"><label class="field">البريد الإلكتروني<input name="e" maxlength="254" type="email" autocomplete="email" dir="ltr"></label><label class="field">الموضوع<select name="t">${topics.map((t,i)=>`<option${(arg==='fitting'?i===0:i===2)?' selected':''}>${t}</option>`).join('')}</select></label></div><label class="field">الرسالة<textarea name="m" required maxlength="4000" rows="5"></textarea></label><button class="button wide">إرسال الرسالة</button><p class="small ct-note">عند الإرسال نحفظ بيانات التواصل ورسالتك لدى أورثو سيرف لمتابعة طلبك.</p></form></section><aside class="ct-side">${hours.length?`<div class="ct-side-card"><h3>ساعات العمل</h3><dl class="ct-hours">${hours.map(h=>`<div><dt>${esc(h.days)}</dt><dd dir="ltr">${esc(h.time)}</dd></div>`).join('')}</dl></div>`:''}${addr.length?`<div class="ct-side-card"><h3>عنواننا</h3><p dir="auto"><b>${esc(c.legalName||'OrthoServ')}</b><br>${addr.map(esc).join('<br>')}</p><a class="text-link" href="${esc(mapUrl)}" target="_blank" rel="noopener noreferrer">احصل على الاتجاهات ↗</a></div>`:''}<div class="ct-side-card ct-pro"><span class="eyebrow">FOR PROFESSIONALS</span><h3>مركز، عيادة أو مستشفى؟</h3><p>لطلبات التجهيز، وتوريد المراكز، واستفسارات الشراكة، استخدم قناة حلول المراكز.</p><a class="button ghost" href="#business">حلول المراكز <span>←</span></a></div></aside></div></div>${fittingBanner()}`;$('#ctFormEl').onsubmit=async e=>{
 e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f)),api=window.OrthoLeads,url=api?.url(),note=f.querySelector('.ct-note'),button=f.querySelector('button');
 const say=(ar,en)=>{note.textContent=(document.documentElement.lang||'ar').startsWith('en')?en:ar};
 if(!url){say('استخدم بيانات التواصل أعلاه لمراسلة الفريق.','Please use the contact details above to reach our team.');return}
 const name=String(d.n||'').replace(/\s+/g,' ').trim(),phone=api.phone('+966',d.p),email=String(d.e||'').trim(),subject=String(d.t||'').trim(),message=String(d.m||'').trim();
 if(name.length<2||name.length>80||!phone||email.length>254||subject.length>160||message.length<1||message.length>4000){say('راجع الاسم ورقم الهاتف والرسالة (حتى 4000 حرف).','Check your name, phone and message (up to 4,000 characters).');return}
 const payload={kind:'contact_form',name,...phone,email,subject,message,...api.context()},fingerprint=JSON.stringify(payload);
 if(f._leadFingerprint!==fingerprint){f._leadFingerprint=fingerprint;f._leadId=crypto.randomUUID()}
 button.disabled=true;note.setAttribute('role','status');say('جارٍ الإرسال…','Sending…');
 try{const r=await fetch(url,{method:'POST',headers:{'Content-Type':'text/plain'},credentials:'omit',referrerPolicy:'no-referrer',body:JSON.stringify({id:f._leadId,...payload})});if(!r.ok)throw Error('send');
 f.reset();delete f._leadId;delete f._leadFingerprint;say('وصلتنا رسالتك. سيتواصل معك فريق أورثو سيرف.','Your message has been received. The OrthoServ team will contact you.');
 }catch{say('تعذّر إرسال الرسالة. بياناتك ما زالت هنا؛ حاول مرة أخرى.','Could not send your message. Your entries are still here; please retry.')}finally{button.disabled=false}
};window.scrollTo({top:0,behavior:'instant'});if(arg==='fitting')requestAnimationFrame(()=>$('#ctForm').scrollIntoView({behavior:'smooth',block:'start'}))}
