$('#searchForm').onsubmit=e=>{e.preventDefault();query=$('#search').value.trim();filterBrand='';filterMethod='';filterGroup='';page=1;if(location.hash==='#catalog'){catalog('all');main.scrollIntoView()}else location.hash='catalog'};
