const cmsReady=window.OrthoCMSReady||Promise.reject(new Error('CMS dependency unavailable'));
cmsReady.then(()=>Promise.all([fetch('products.json').then(r=>{if(!r.ok)throw Error('catalog');return r.json()}),fetch('home-identities.json').then(r=>r.json()).catch(()=>({brands:[],clients:[]})),fetch('experiences/juzo/products.json').then(r=>{if(!r.ok)throw Error('juzo');return r.json()}).catch(()=>[])])).then(([d,identities,juzo])=>{homeIdentities=identities;homeJuzoProducts=(Array.isArray(juzo)?juzo:[]).filter(p=>p&&p.visible!==false);Object.assign(categories,window.OrthoCMS.settings.categories);Object.assign(groups,window.OrthoCMS.settings.groups);products=window.OrthoCMS.prepareProducts(d.products);cart=(Array.isArray(cart)?cart:[]).filter(x=>x&&(byId(x.id)?.method==='buy'||window.OrthoJuzoStore?.isEnquiry(x)&&byId(x.id)?.brand==='Juzo')&&Number.isInteger(x.qty)&&x.qty>0&&x.qty<=99);saved=(Array.isArray(saved)?saved:[]).filter(id=>byId(id));if(window.OrthoJuzoStore)cart=window.OrthoJuzoStore.migrate(products,cart);updateCounts();route()}).catch(()=>{main.innerHTML='<div class="wrap empty"><h1>تعذّر تحميل المنتجات</h1><p>أعد فتح الموقع من رابط المتجر ثم حدّث الصفحة.</p><button class="button" onclick="location.reload()">حاول مرة أخرى</button></div>'});
/* Chat-with-us widget: small floating button that opens a callback / WhatsApp panel */
(function(){if(document.getElementById('chatFab'))return;const $=s=>document.querySelector(s);
document.body.insertAdjacentHTML('beforeend',`<button id="chatFab" class="chat-fab" type="button" aria-label="تحدّث معنا" aria-expanded="false" aria-controls="chatPanel"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 20l1.3-4.2A8 8 0 1 1 8.4 18.8L4 20Z"/><path d="M9 11h6M9 14h4"/></svg></button><section id="chatPanel" class="chat-panel" role="dialog" aria-labelledby="chatTitle" hidden><header><div><h2 id="chatTitle">تحدّث معنا</h2><p>فريقنا بجانبك</p></div><button type="button" class="chat-close" aria-label="إغلاق">×</button></header><form id="chatForm"><p class="chat-lead">اكتب اسمك ورقم هاتفك، ليتمكّن أحد الزملاء من متابعتك عند الحاجة.</p><input name="n" required maxlength="80" autocomplete="name" placeholder="الاسم" aria-label="الاسم"><div class="chat-phone"><input name="p" required type="tel" autocomplete="tel-national" dir="ltr" inputmode="tel" placeholder="رقم الهاتف" aria-label="رقم الهاتف"><input name="c" class="chat-cc" value="+966" dir="ltr" aria-label="رمز الدولة" inputmode="tel"></div><button class="chat-go">ابدأ المحادثة</button><p class="chat-note" id="chatNote"></p></form><div class="success chat-done" id="chatDone" hidden><b>✓</b><h3 id="chatDoneTitle">التفاصيل جاهزة</h3><p id="chatDoneText">يمكنك مراسلتنا من صفحة <a href="#contact">تواصل معنا</a>.</p></div></section>`);
const fab=$('#chatFab'),panel=$('#chatPanel'),form=$('#chatForm'),note=$('#chatNote');
/* Lead capture: the visitor's name and phone go to the OrthoServ analytics worker (/lead) only when this form is submitted.
   The endpoint is derived from the analytics setting; with no valid endpoint nothing is sent and the old "not saved" notice stays true. */
const SRC_RE=/^(?:\(direct\)|\(other\)|[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?)$/;
const leadUrl=()=>{try{const a=window.OrthoCMS?.settings?.analytics;if(!a||a.enabled!==true||typeof a.endpoint!=='string')return '';const u=new URL(a.endpoint);if(location.protocol!=='https:'||/^(localhost|127\.)/.test(location.hostname)||u.protocol!=='https:'||u.username||u.password||u.search||u.hash||u.pathname!=='/collect')return '';u.pathname='/lead';return u.href}catch{return ''}};
const leadContext=()=>{const[view='home',arg='']=(location.hash.slice(1)||'home').split('/');const page=['home','catalog','product','offers','business','brand','partners','contact'].includes(view)?view:'home';const out={page,device:innerWidth<=599?'mobile':innerWidth<=1023?'tablet':'desktop'};if(page==='product'&&/^[a-zA-Z0-9][a-zA-Z0-9_-]{0,179}$/.test(arg))out.productId=arg;let host='(direct)';try{const saved=sessionStorage.getItem('ortho-analytics-source-v1');if(saved&&saved.length<=253&&SRC_RE.test(saved))host=saved;else if(document.referrer){const r=new URL(document.referrer);if(['http:','https:'].includes(r.protocol)&&r.hostname!==location.hostname)host=/^[a-z0-9.-]+$/.test(r.hostname)&&!/^\d[\d.]*$/.test(r.hostname)&&r.hostname.length<=253&&SRC_RE.test(r.hostname)?r.hostname:'(other)'}}catch{}out.sourceHost=host;return out};
/* The worker stores country code + number as one international string, so any split of the same digits is equivalent. */
const leadPhone=(cc,raw)=>{let code=String(cc||'').replace(/\D/g,'').replace(/^0+/,'');if(!code||code.length>4)code='966';const text=String(raw||'').trim(),intl=/^(\+|00)/.test(text);let digits=text.replace(/\D/g,'');if(intl)digits=digits.replace(/^00/,'');if(digits.startsWith(code)&&(intl||digits.length-code.length>=8))digits=digits.slice(code.length);else if(intl){code=digits.slice(0,1);digits=digits.slice(1)}digits=digits.replace(/^0+/,'');const total=code.length+digits.length;return digits.length>=6&&digits.length<=20&&total>=8&&total<=15?{cc:'+'+code,phone:digits}:null};
window.OrthoLeads={url:leadUrl,context:leadContext,phone:leadPhone};
const open=v=>{panel.hidden=!v;fab.setAttribute('aria-expanded',v);fab.classList.toggle('is-open',v);if(v){form.hidden=false;$('#chatDone').hidden=true;const{wa}=ctInfo();note.textContent=leadUrl()?(wa?'عند الإرسال نحفظ اسمك ورقمك لدى أورثو سيرف ليتواصل معك فريقنا، ثم تُفتح محادثة واتساب.':'عند الإرسال نحفظ اسمك ورقمك لدى أورثو سيرف ليتواصل معك فريقنا.'):wa?'أكمل المحادثة مع فريقنا في واتساب.':'تواصل مع فريق أورثو سيرف من صفحة تواصل معنا.';form.querySelector('input').focus()}};
fab.onclick=()=>open(panel.hidden);panel.querySelector('.chat-close').onclick=()=>{open(false);fab.focus()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!panel.hidden){open(false);fab.focus()}});
form.onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form)),{wa}=ctInfo(),url=leadUrl(),en=window.OrthoLang==='en';
const name=String(d.n||'').replace(/\s+/g,' ').trim(),phone=leadPhone(d.c,d.p),button=form.querySelector('.chat-go');
if(name.length<2||name.length>80||!phone){note.textContent=en?'Check your name and phone number.':'تأكد من كتابة الاسم ورقم الهاتف بشكل صحيح.';return}
if(!url){if(wa){window.open('https://wa.me/'+wa+'?text='+encodeURIComponent((en?'Hello, my name is ':'مرحبًا، أنا ')+name+' ('+phone.cc+phone.phone+')'),'_blank','noopener');open(false);notify(en?'Continue your conversation in WhatsApp.':'أكمل المحادثة في واتساب.')}else note.textContent=en?'Please reach our team through the contact page.':'تواصل مع الفريق من صفحة تواصل معنا.';return}
button.disabled=true;note.textContent=en?'Sending…':'جارٍ الإرسال…';
try{const payload={kind:'chat_popup',name,...phone,...leadContext()},fingerprint=JSON.stringify(payload);if(form._fingerprint!==fingerprint){form._fingerprint=fingerprint;form._leadId=crypto.randomUUID()}
const r=await fetch(url,{method:'POST',body:JSON.stringify({id:form._leadId,...payload}),headers:{'Content-Type':'text/plain'},credentials:'omit',keepalive:true,referrerPolicy:'no-referrer'});if(!r.ok)throw Error('send');
open(false);form.reset();form.elements.c.value='+966';delete form._leadId;delete form._fingerprint;notify(en?'Your details have been received. Our team will contact you.':'وصلتنا بياناتك. سيتواصل معك فريق أورثو سيرف.');fab.focus();
}catch{note.textContent=en?'Could not send. Your entries are still here; please retry.':'تعذّر الإرسال. بياناتك ما زالت هنا؛ حاول مرة أخرى.'}finally{button.disabled=false}}})();
